const linha = $input.first().json;

const total = Number(linha.total) || 0;
const assinados = Number(linha.assinados) || 0;
const pendentes = Number(linha.pendentes) || 0;
const recusados = Number(linha.recusados) || 0;
const taxaMediaHoras = linha.taxa_media_horas != null ? Number(linha.taxa_media_horas) : null;

const percentual = total > 0 ? Math.round((assinados / total) * 1000) / 10 : 0;

const blocosPreenchidos = Math.round(percentual / 5);
const barra = '█'.repeat(blocosPreenchidos) + '░'.repeat(20 - blocosPreenchidos);

const dataRelatorio = new Date().toLocaleDateString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{
  json: {
    data_relatorio: dataRelatorio,
    total,
    assinados,
    pendentes,
    recusados,
    percentual_assinados: percentual,
    taxa_media_horas: taxaMediaHoras,
    barra_progresso: barra
  }
}];
